        const x=i*gap-camX*par, rnd=hash(i+layer*911), h=(72+rnd*95)*(layer===0?.72:1), base=H*(layer===0?.74:.77)-camY*(layer===0?.27:.46)+Math.sin(i*.39)*10;
        if(x<-100||x>W+100)continue;
